WITH with_dims AS (SELECT src.*, b.discount FROM payments src LEFT JOIN orders b ON src.order_id = b.id), joined AS (SELECT s.*, b.order_date, b.discount AS order_discount, b.channel FROM with_dims s LEFT JOIN orders b ON s.order_id = b.id), joined_payments AS (SELECT src.*, o.order_date AS order_order_date, o.status AS order_status FROM joined src LEFT JOIN orders o ON src.order_id = o.id) SELECT *, NTILE(4) OVER w_recent AS discount_bucket, NTILE(4) OVER w_running AS amount_bucket FROM joined_payments WINDOW w_recent AS (PARTITION BY channel ORDER BY discount, id), w_running AS (ORDER BY amount DESC, id);
